<script setup>
import {computed} from 'vue'
import PixelSprite from './PixelSprite.vue'
import {getSpriteFrame} from './spriteAtlas.js'
import {highTierRevealView} from './presentationViews.js'
const props=defineProps({receipt:{type:Object,default:null},actualUnit:{type:Object,default:null},
  revealed:{type:Boolean,default:true},qualityVisible:{type:Boolean,default:true},kind:{type:String,default:'recruit'},
  enabled:{type:Boolean,default:true},reducedMotion:Boolean,speed:{type:Number,default:1},
  controls:{type:Boolean,default:true},compact:Boolean})
const emit=defineEmits(['skip','speed'])
const view=computed(()=>highTierRevealView(props.receipt,{actualUnit:props.actualUnit,revealed:props.revealed,qualityVisible:props.qualityVisible,kind:props.kind}))
const sprite=computed(()=>view.value?.actualUnit?getSpriteFrame(view.value.actualUnit):null)
</script>
<template>
  <section v-if="view" class="high-tier-reveal" :class="{compact,concealed:!view.revealed,prismatic:view.revealed && view.grade===6,'motion-off':reducedMotion || !enabled}" :style="{'--reveal-ink':view.tone,'--reveal-speed':speed===2?2:1}" :data-high-tier-grade="view.revealed?view.grade:undefined" :data-recruit-destination="view.revealed?view.status:undefined" aria-label="高阶主将实际揭晓">
    <template v-if="view.revealed">
      <header class="high-tier-heading"><span>{{ view.fusion?'融合升品':'主将揭晓' }}</span><strong><template v-if="view.previousQuality">{{ view.previousQuality }} <i>→</i> </template>{{ view.quality }}</strong><small>{{ view.suit }}{{ view.rank }}<template v-if="view.level"> · {{ '★'.repeat(view.level) }}</template></small></header>
      <div class="high-tier-hero">
        <div class="high-tier-portrait" :data-actual-unit-id="view.actualUnit?.id">
          <i class="high-tier-halo" aria-hidden="true"></i><span class="high-tier-plinth" aria-hidden="true"></span>
          <PixelSprite v-if="sprite" class="high-tier-commander-model" v-bind="sprite" :label="view.name+' · '+view.quality+' · '+view.primary"/>
          <span v-else class="high-tier-missing">{{ view.suit || '♛' }}<small>主将形象未记录</small></span>
        </div>
        <div class="high-tier-identity"><h3>{{ view.name }}</h3><p class="high-tier-primary">主职 · {{ view.primary || '未记录' }}</p><div class="high-tier-jobs"><span v-for="job in view.inherited" :key="job.id" :title="job.skill">兼修 {{ job.name }}</span><small v-if="!view.inherited.length">单一主职</small></div><p class="high-tier-destination" :class="{reserve:view.status==='reserve'}">{{ view.destination }}</p><p v-if="view.reason" class="high-tier-reason">{{ view.reason }}</p></div>
      </div>
      <div v-if="view.keyChanges.length" class="high-tier-key-changes"><div v-for="row in view.keyChanges" :key="row.stat" :data-reveal-stat="row.stat"><small>{{ row.label }}</small><strong><template v-if="row.before!==null">{{ row.beforeText }} <i>→</i> </template>{{ row.afterText }}<em v-if="row.unit">{{ row.unit }}</em></strong><b v-if="row.deltaText">{{ row.deltaText }}</b><span v-else>实际结算后</span></div></div>
      <details v-if="view.rows.length" class="high-tier-details"><summary class="key-disclosure">完整实际属性 <span>{{ view.rows.length }} 项</span></summary><dl><div v-for="row in view.rows" :key="row.stat"><dt>{{ row.label }}</dt><dd><template v-if="row.before!==null">{{ row.beforeText }} → </template>{{ row.afterText }}{{ row.unit }}<b v-if="row.deltaText">（{{ row.deltaText }}）</b></dd></div></dl><p>仅展示已结算记录；没有前值的属性不推算增量。</p></details>
      <footer v-if="controls" class="high-tier-controls"><small>{{ reducedMotion?'减少动态':!enabled?'演出已关闭':'实际主将亮相' }}</small><button v-if="enabled && !reducedMotion" class="key-tab high-tier-speed" type="button" :aria-label="'当前'+speed+'倍速，切换亮相速度'" @click="emit('speed',speed===2?1:2)">{{ speed }}×</button><button class="key-link high-tier-skip" type="button" @click="emit('skip')">收起亮相 / 跳过欢呼</button></footer>
    </template>
    <span v-else class="high-tier-placeholder">主将与品质将在揭晓后显示</span>
  </section>
</template>
