ols>small{margin-right:auto;font-size:9px;color:#ab98b3}.high-tier-controls button{min-height:28px;font-size:10px;padding:3px 6px}.high-tier-missing{position:relative;display:grid;gap:8px;text-align:center;color:var(--reveal-ink);font:48px Georgia,serif}.high-tier-missing>small{font:9px sans-serif;color:#a795ad}.high-tier-placeholder{font-size:11px;color:#b9a6bd}.high-tier-reveal.concealed{padding:7px 9px;border-color:#6f5a64;min-height:35px}.high-tier-reveal.compact{padding:7px 8px}.high-tier-reveal.compact .high-tier-hero,.high-tier-reveal.compact .high-tier-portrait{min-height:124px;height:124px}.high-tier-reveal.compact .high-tier-commander-model{height:122px;width:108px}.high-tier-reveal.compact .high-tier-identity h3{font-size:21px}
